import sys

ref, idx, reads = sys.argv[1], sys.argv[2], sys.argv[3]
kmers = {}
for i, line in enumerate(open(idx)):
    kmers[line.strip()] = i

hits = 0
for line in open(reads):
    if not line.startswith("@"):
        hits += kmers.get(line.strip()[:4], 0)

print(hits)
